const skillImage=id=>`https://ligmar.io/game/assets/images/skills/${id}.webp`;
const rows=[
 ['Маг','Морозная чума','14b1a679ae4080668655cfd1bbc9ce75','Магический','15 с','Наносит базовый магический урон и магический DOT. Замедляет цель и может обездвижить её.'],
 ['Жрец','Испепеление','15a1a679ae4080e09e7cd7a888c91a1c','Магический','15 с','Наносит базовый магический урон и магический DOT.'],
 ['Лучник','Медвежий коготь','2801a679ae4080d8af57ef75e7f46607','Физический','15 с','Наносит базовый физический урон и физический DOT.'],
 ['Лучник','Клык змеи','1591a679ae4080518dfcc52449c8d317','Магический','15 с','Первоначальный удар физический, последующий DOT — магический.'],
 ['Убийца','Удар по артерии','1591a679ae4080e29996c5f02fbfbbf2','Физический','9 с','Наносит базовый физический урон, урон от снаряжения и физический DOT.'],
 ['Воин','Рассекающий удар','1441a679ae4080c893a1dda274bb8c4b','Физический','15 с','Наносит базовый физический урон и физический DOT.'],
 ['Страж','Кровавый зов','1571a679ae4080338343e3a09b31a450','Физический','15 с','Наносит базовый физический урон и физический DOT, провоцирует монстров и не промахивается.'],
 ['Страж','Жгучая рана','1571a679ae408065959fdd315f787879','Физический','15 с','Наносит базовый физический урон и физический DOT. Недоступна в состоянии «Железная воля».'],
 ['Страж','Каленный ураган','2821a679ae4080418c3eff3488087ced','Магический · по ближним целям','15 с','Бьёт ближайших противников физическим уроном и накладывает магический DOT. Недоступен в состоянии «Железная воля».']];

export function mountDotGuide(app){
 document.title='DOT: периодический урон • LigmarBD';
 app.innerHTML=`<article class="guide-article">
 <a class="guide-back" href="#guides">← Все гайды</a>
 <span class="eyebrow">БОЕВЫЕ МЕХАНИКИ · ТЕСТОВЫЙ ГАЙД</span>
 <h1>DOT: периодический урон</h1><p class="guide-lead">Как работают тики, какие умения их накладывают и как физические и магические кровотоки взаимодействуют с защитой, сопротивлением и PvP.</p>
 <p>После наложения DOT наносит отдельные тики. Первоначальный удар и сам DOT считаются разными частями умения.</p>
 <h2>DOT-умения персонажей</h2><div class="guide-table-wrap"><table><thead><tr><th>Класс</th><th>Умение</th><th>Тип DOT</th><th>Длительность</th></tr></thead><tbody>${rows.map(([owner,name,id,type,duration,description])=>`<tr><td>${owner}</td><td><span class="guide-skill-name" title="${description}" tabindex="0"><img src="${skillImage(id)}" alt="" loading="lazy"><strong>${name}</strong></span></td><td><span class="${type.startsWith('Физический')?'guide-damage-physical':'guide-damage-magic'}">${type}</span></td><td>${duration}</td></tr>`).join('')}</tbody></table></div>
 <p>Тип первоначального удара не обязательно совпадает с DOT: <strong>«Клык змеи» бьёт физическим уроном, а тики у него магические.</strong></p>
 <h2>Как считаются тики</h2><ul>
 <li>У всех перечисленных DOT в данных указан интервал <strong>1 секунда</strong>.</li>
 <li>Урон тика задан отдельным числом для каждого уровня умения. В этих эффектах нет коэффициента от оружия или основного стата персонажа.</li>
 <li>Суммарный DOT в описании — сумма тиков, <strong>без первоначального удара</strong>.</li></ul>
 <div class="guide-examples"><div><small>Морозная чума · уровень 8</small><strong class="guide-damage-magic">192 × 15 = 2880</strong><span>до возможных снижений</span></div><div><small>Удар по артерии · уровень 7</small><strong class="guide-damage-physical">290 × 9 = 2610</strong><span>до возможных снижений</span></div></div>
 <p>Для «Морозной чумы» в разобранных боях первый тик происходил сразу после наложения, остальные — примерно на отметках <strong>1…14 секунд</strong>. Для остальных DOT такой порядок пока принят в калькуляторе как допущение.</p>
 <h2>Повторное наложение и попадание</h2><p>По записанным проверкам:</p><ul>
 <li><strong>Одинаковый DOT заменяется новым</strong>, даже от другого персонажа. Более слабая версия тоже может заменить сильную.</li>
 <li><strong>Разные DOT работают одновременно.</strong></li>
 <li>Тики <strong>не критуют</strong>; первоначальный удар может критовать.</li>
 <li>При промахе физического удара его DOT не накладывается, если у умения нет исключения.</li>
 <li>Отсутствие отдельной проверки уклонения на каждом тике пока остаётся предварительным правилом.</li></ul>
 <aside class="guide-note"><strong>Для ротации</strong><p>Обновляя DOT слишком рано, ты заменяешь оставшиеся тики, а не добавляешь вторую копию.</p></aside>
 <h2>Защита, сопротивление и PvP</h2><div class="guide-examples guide-dot-rules"><div><small>Физический DOT</small><strong>Игнорирует защиту</strong><span>Количество физической защиты цели не уменьшает тики.</span></div><div><small>Магический DOT</small><strong>Учитывает сопротивление</strong><span>Чем выше сопротивление цели, тем меньше урон тиков.</span></div><div><small>PvP</small><strong>Урон × 0,25</strong><span>По игрокам кровоток наносит в четыре раза меньше урона.</span></div></div>
 <p>Физический кровоток наносит одинаковый урон целям с разным количеством защиты. Поэтому изменение защиты игрока с <strong>3532 до 2119</strong> до наложения «Удара по артерии» не изменило тики: в обоих случаях прошло по <strong class="guide-damage-physical">72</strong>.</p>
 <p>В PvE «Удар по артерии» наносил по <strong class="guide-damage-physical">290</strong> за тик как обычному мобу 26-го уровня, так и чемпиону 28-го уровня. В PvP действует отдельный множитель: <strong class="guide-damage-physical">290 ÷ 4 = 72,5</strong>, после округления вниз — <strong class="guide-damage-physical">72</strong>.</p>
 <p>Магические кровотоки работают иначе: их тики уменьшаются сопротивлением цели. Поэтому «Морозная чума» может наносить разный урон по разным мобам, даже если используется один уровень умения.</p>
 <aside class="guide-note"><strong>Что учитывать в расчёте</strong><p>Для физического DOT не применяй защиту. Для магического DOT применяй сопротивление. В PvP дополнительно уменьши получившийся урон в четыре раза.</p></aside>
 <h2>DOT у монстров</h2><ul><li><strong>Физические:</strong> Кровавая баня, Рана бездны, Рассекающий залп.</li><li><strong>Магические:</strong> Кровавый тайфун, Гнев проклятых, Жало агонии.</li></ul>
 <p>У найденных вариантов тоже указан секундный интервал и длительность 15 секунд. Для них действуют те же правила: физические тики игнорируют защиту, магические уменьшаются сопротивлением, а в PvP урон дополнительно делится на четыре.</p>
 <a class="guide-back" href="#guides">← Вернуться к гайдам</a></article>`;
}
